My solution now looks like this:
```cs
public abstract class Test {
    [property: JsonProperty("data")] public CsvDataListCsvData Data {get; set;}
}
public CsvData {
    public string Header001 {get; set;}
    public string Header002 {get; set;}
    public DateTime HeaderDateTime {get; set;}
}

// Generic Types don't work in annotations, so we need a wrapper class with explicit type.
[JsonConverter(typeof(CsvConverter<CsvDataList<CsvData>, CsvData>))]
public class CsvDataListCsvData : CsvDataList<CsvData> {}


// [JsonConverter(typeof(CsvConverter<CsvDataList<T>, T>))]
public class CsvDataList<T> : List<T>
{
    public override int GetHashCode() => base.GetHashCode();
    public override string? ToString() => base.ToString();
}
public class CsvConverter<TList, TEntry> : JsonConverter<TList> where TList : List<TEntry>, new()
{
    private readonly CsvConfiguration csvConfiguration = new CsvConfiguration(CultureInfo.InvariantCulture)
    {
        ShouldQuote = args => true,
        LineBreakInQuotedFieldIsBadData = true,
        Delimiter = ",",
    };

    public override TList? ReadJson(JsonReader reader, Type objectType, TList? existingValue, bool hasExistingValue, JsonSerializer serializer)
    {
        // copy reader.Value into local variable to avoid
        // time-of-check to time-of-use (TOCTOU) vulnerability
        string readerValue = reader.Value as string ?? "";
        if (string.IsNullOrEmpty(readerValue))
        {
            return new TList();
        }
        using StringReader stringReader = new StringReader(readerValue);
        using CsvReader csvReader = new CsvReader(stringReader, csvConfiguration);
        List<TEntry> dataList = csvReader.GetRecords<TEntry>().ToList();
        TList data = new TList();
        data.AddRange(dataList);
        return data;
    }

    public override void WriteJson(JsonWriter writer, TList? value, JsonSerializer serializer)
    {
        StringBuilder csvString = new StringBuilder();

        using StringWriter stringWriter = new StringWriter(csvString);
        using CsvWriter csvWriter = new CsvWriter(stringWriter, csvConfiguration);
        csvWriter.WriteRecords(value);
        writer.WriteValue(csvString.ToString());
    }
}
```

