If you want the deserialization to fail if the json contains floating point number or string instead of an expected true integer number, you can realize this with the help of a custom JsonConverter like:
```C#
public class StrictIntegerConverter : JsonConverter
{
    private static readonly HashSet<Type> _intTypes = new HashSet<Type>
    {
        typeof(long), typeof(ulong),
        typeof(int), typeof(uint),
        typeof(short), typeof(ushort),
        typeof(byte), typeof(sbyte)
    };


    public override bool CanWrite => false;

    public override bool CanConvert(Type objectType) => _intTypes.Contains((objectType));

    public override object ReadJson(JsonReader reader, Type objectType, object? existingValue, JsonSerializer serializer)
    {
        Exception? conversionException = null;

        if (_intTypes.Contains(reader.Value.GetType()))
        {
            try
            {
                return Convert.ChangeType(reader.Value, objectType);
            }
            catch (Exception ex)
            {
                conversionException = ex;
            }
        }

        var jli = (IJsonLineInfo) reader;
        var message = conversionException?.Message ?? "Not an integer number.";
        throw new JsonSerializationException(
            $"{message} Path '{reader.Path}, line {jli.LineNumber}, position {jli.LinePosition}",
            reader.Path,
            jli.LineNumber,
            jli.LinePosition,
            conversionException
        );
    }

    public override void WriteJson(JsonWriter writer, object? value, JsonSerializer serializer)
        => throw new NotImplementedException();
}
```

