`StringEscapeHandling` won't help you, as this setting is for writing / serializing into json, not the other way around. The derserializer itself does not have such a feature built-in either. Fortunately, Newtonsoft.Json is flexible enough to allow you to address your problem with some additional code.

You can filter out any undesired (control) characters from strings during deserialization with the help of a custom JsonConverter:

    public class StringsWithoutNonprintablesConverter : JsonConverter<string>
    {
        public override string ReadJson(JsonReader reader, Type objectType, string existingValue, bool hasExistingValue, JsonSerializer serializer)
        {
            if (reader.TokenType != JsonToken.String)
                throw new InvalidDataException("Json data is not a string value");

            var s = (string) reader.Value;
            return (s.Any(char.IsControl)) ? new string(s.Where(c => !char.IsControl(c)).ToArray()) : s;
        }

        public override void WriteJson(JsonWriter writer, string value, JsonSerializer serializer)
        {
            writer.WriteValue(value);
        }
    }

