Please note that this doesn't support fields on objects. You should use `prop.DeclaringTpe.GetField(prop.PropertyName).GetValue(instance` to support fields.

Furthermore, if someone uses the `[JsonProperty("PropertyName")]` on a field or property, `prop.DeclaringType.GetProperty(prop.PropertyName)` won't find the property on the object  as it will take the overwritten name, you have to use `property.UnderlyingName`.

Here's an example:

```
public class OptionalShouldSerializeContractResolver : DefaultContractResolver
{
    protected override JsonProperty CreateProperty(MemberInfo member, MemberSerialization memberSerialization)
    {
        JsonProperty property = base.CreateProperty(member, memberSerialization);
    
        if (property.PropertyType.IsGenericType && property.PropertyType.GetGenericTypeDefinition() == typeof(Optional<>))
        {
            property.ShouldSerialize =
                instance =>
                {
                    IMember? propertyOrField = instance.GetType().GetPropertyOrField(property.UnderlyingName);

                    if (propertyOrField == null)
                        throw new Exception("Member should surely be found on class?");

                    IOptional optional = (IOptional)propertyOrField.GetValue(instance);
                    return optional.IsDefined;
                };
        }
    
        return property;
    }
}
```

