public class MinDateConverter : DateTimeConverterBase {
    public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer) {
        DateTimeOffset? value = null;

        if (reader.Value != null) {
            if (reader.Value is DateTime dateTime) {
                value = dateTime != DateTime.MinValue ? dateTime : DateTimeOffset.MinValue;
            }

            if (value == DateTimeOffset.MinValue) {
                value = null;
            }
        }

        return value;
    }

    public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer) {
        if (value is DateTimeOffset minDateTimeOffset && minDateTimeOffset == DateTimeOffset.MinValue ||
            value is DateTime minDateTime && minDateTime == DateTime.MinValue) {
            writer.WriteNull();
            return;
        }

        writer.WriteValue(value);
    }
